style.css:
@-moz-document domain("youtube.com") {
/* ---------- MAIN COLORS ---------- */

:root {
    --yt-spec-brand-background-primary: #090016 !important;
    --yt-spec-general-background-a: #120024 !important;
    --yt-spec-general-background-b: #1a0033 !important;
    --yt-spec-text-primary: #f4d8ff !important;
    --yt-spec-text-secondary: #c7a8ff !important;
    --yt-spec-call-to-action: #ff7bd5 !important;
    --yt-spec-brand-button-background: #8a5cff !important;
}

/* ---------- BACKGROUND IMAGE ---------- */

body,
ytd-app,
#content.ytd-app {
    background: url("https://wallpapercave.com/wp/wp2465928.jpg") center center fixed !important;
    background-size: cover !important;
}

/* Adds dreamy overlay */
ytd-app::before {
    content: "";
    position: fixed;
    inset: 0;
    background: linear-gradient(
        rgba(8, 0, 20, 0.75),
        rgba(23, 0, 45, 0.8)
    );
    pointer-events: none;
    z-index: 0;
}

/* ---------- SIDEBAR + TOPBAR ---------- */

#guide-content,
ytd-mini-guide-renderer,
#masthead-container,
ytd-watch-flexy,
ytd-rich-grid-renderer {
    background: rgba(10, 0, 25, 0.78) !important;
    backdrop-filter: blur(10px);
}

/* ---------- VIDEO CARDS ---------- */

ytd-rich-item-renderer,
ytd-video-renderer,
ytd-grid-video-renderer {
    background: rgba(26, 0, 51, 0.55) !important;
    border-radius: 18px !important;
    transition: 0.3s ease;
}

ytd-rich-item-renderer:hover,
ytd-video-renderer:hover {
    transform: translateY(-3px);
    box-shadow: 0 0 20px rgba(255, 123, 213, 0.35);
}

/* ---------- SEARCH BAR ---------- */

#search-form,
#search-input {
    background: rgba(255,255,255,0.08) !important;
    border-radius: 25px !important;
}

/* ---------- BUTTONS ---------- */

button,
.yt-spec-button-shape-next {
    border-radius: 20px !important;
}

/* ---------- PROGRESS BAR ---------- */

/* Main progress color */
.ytp-play-progress {
    background: #ff7bd5 !important;
}

/* Buffer bar */
.ytp-load-progress {
    background: rgba(255,255,255,0.25) !important;
}

/* Steven head thumb */
.ytp-scrubber-button {
    background: url("https://upload.wikimedia.org/wikipedia/en/f/fd/Steven_Universe.png") center center no-repeat !important;
    background-size: contain !important;
    background-color: transparent !important;
    width: 34px !important;
    height: 34px !important;
    border: none !important;
    margin-top: -12px !important;
    box-shadow: 0 0 12px rgba(255, 123, 213, 0.7);
}

/* ---------- TEXT ---------- */

#video-title,
yt-formatted-string,
h1,
h2,
h3,
h4,
span,
a {
    color: #f7deff !important;
}

/* ---------- SCROLLBAR ---------- */

::-webkit-scrollbar {
    width: 10px;
}

::-webkit-scrollbar-thumb {
    background: linear-gradient(#ff7bd5, #8a5cff);
    border-radius: 20px;
}

::-webkit-scrollbar-track {
    background: #120024;
}
}
